extends CharacterBody2D

signal reached

@export var movement_speed: float = 200.0
@export var arrival_distance: float = 8.0

var reached: bool = false

@onready var nav_agent: NavigationAgent2D = $NavigationAgent2D

func _ready() -> void:
	nav_agent.target_reached.connect(_on_target_reached)

func set_destination(target: Vector2) -> void:
	reached = false
	nav_agent.target_position = target

func _on_target_reached() -> void:
	reached = true
	reached.emit()

func _physics_process(_delta: float) -> void:
	if reached:
		velocity = Vector2.ZERO
		move_and_slide()
		return
	if nav_agent.is_navigation_finished():
		velocity = Vector2.ZERO
		move_and_slide()
		return
	var map_rid: RID = get_world_2d().navigation_map
	if NavigationServer2D.map_get_iteration_id(map_rid) == 0:
		velocity = Vector2.ZERO
		move_and_slide()
		return
	var next_pos: Vector2 = nav_agent.get_next_path_position()
	var dir: Vector2 = next_pos - global_position
	if dir.length() > arrival_distance:
		velocity = dir.normalized() * movement_speed
	else:
		velocity = dir
	move_and_slide()
EOF

python3 << 'PYEOF'
script = '''extends Node2D

@onready var region: NavigationRegion2D = $Region
@onready var agent: CharacterBody2D = $Agent
@onready var obstacles: Node2D = $Obstacles
@onready var goal: Marker2D = $Goal

const WALKABLE_MIN := Vector2(0, 0)
const WALKABLE_MAX := Vector2(800, 600)

func _ready() -> void:
	rebake_navigation()

func rebake_navigation() -> void:
	var nav_poly := NavigationPolygon.new()
	var outline := PackedVector2Array([
		WALKABLE_MIN,
		Vector2(WALKABLE_MAX.x, WALKABLE_MIN.y),
		WALKABLE_MAX,
		Vector2(WALKABLE_MIN.x, WALKABLE_MAX.y),
	])
	nav_poly.add_outline(outline)

	for child in obstacles.get_children():
		if child is NavigationObstacle2D and child.vertices.size() >= 3:
			var world_outline := PackedVector2Array()
			for v in child.vertices:
				world_outline.push_back(v + child.global_position)
			nav_poly.add_obstruction_outline(world_outline)

	nav_poly.make_polygons_from_outlines()
	region.navigation_polygon = nav_poly

	var map_rid: RID = region.get_world_2d().navigation_map
	NavigationServer2D.map_force_update(map_rid)

func move_obstacle(name: String, new_position: Vector2) -> void:
	var node := obstacles.get_node_or_null(name)
	if node == null:
		return
	node.global_position = new_position
	rebake_navigation()

func start_navigation() -> void:
	var nav_agent: NavigationAgent2D = agent.get_node("NavigationAgent2D")
	nav_agent.target_position = goal.global_position
	agent.set("reached", false)
	agent.set_destination(goal.global_position)
'''
with open('/home/user/godot_project/scripts/nav_world.gd', 'w') as f:
    f.write(script)
print('done')
PYEOF

